package br.com.logiflow.estoque.kafka;
import br.com.logiflow.estoque.domain.EstoqueService; import br.com.logiflow.estoque.event.PedidoCriadoEvent; import org.apache.kafka.clients.consumer.ConsumerRecord; import org.slf4j.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class PedidoConsumer {private static final Logger log=LoggerFactory.getLogger(PedidoConsumer.class);private final EstoqueService service;public PedidoConsumer(EstoqueService s){service=s;}@KafkaListener(topics="${logiflow.topics.pedido-criado}")public void consumir(PedidoCriadoEvent evento,ConsumerRecord<String,PedidoCriadoEvent> record){log.info("Consumindo eventId={} pedidoId={} topic={} partition={} offset={}",evento.eventId(),evento.pedidoId(),record.topic(),record.partition(),record.offset());service.reservar(evento);}}
